insert into public.stores (public_id, slug, name, initials, tagline, city, area, state, founded, status, rating, reviews_count, details) values
('STR-001', 'k9-guardian-kennels', 'K9 Guardian Kennels', 'KG', 'Titled working-line Malinois and Shepherds for executive homes', 'Abuja', 'Kuje', 'FCT', 2014, 'verified', 4.9, 84, '{"replies":"~1 h","dogsPlaced":212,"hours":"Mon–Sat, 8am–5pm. Visits by appointment.","deliveryAreas":"Abuja, Kaduna, Lagos, Port Harcourt","services":["handover","delivery","imports","training","boarding"],"owner":{"name":"Col. (rtd) Ibrahim Danjuma","title":"Founder and head trainer","yearsWithDogs":26,"bio":"Ibrahim spent two decades with the Army K9 unit before founding the kennel. He still runs every protection assessment himself.","credentials":["Former Army K9 unit instructor","IGP helper certified","SV breed warden course"]},"about":"A 4-acre kennel outside Abuja breeding and importing German and Belgian working lines. Every adult dog is titled or trained to IGP standard before it is listed, and every buyer gets a two-day handover at their gate.","history":[{"year":2014,"text":"Founded in Kuje with two imported German Shepherd females"},{"year":2017,"text":"First IGP-3 titled dog bred in the kennel"},{"year":2020,"text":"Added Belgian Malinois lines from the Netherlands and Belgium"},{"year":2023,"text":"Built a covered training field and a quarantine block"},{"year":2025,"text":"Joined Dogeash and passed its first kennel inspection"}],"inspection":{"status":"passed","date":"November 2025","by":"Dogeash inspection team","checks":["Clean, shaded kennel runs","Vet records for every dog","Protection levels tested on site","Microchips scanned and matched"]},"care":[{"providerId":"CARE-01","relationship":"Our vet"},{"providerId":"CARE-02","relationship":"Our handover trainer"},{"providerId":"CARE-03","relationship":"Kennel runs we install"}],"reviewSamples":[{"name":"Aisha B.","city":"Maitama","date":"Aug 2026","rating":5,"dog":"Sarge","text":"The two-day handover was worth it on its own. Our driver and house staff all know the commands now."},{"name":"Tunde O.","city":"Asokoro","date":"May 2026","rating":5,"dog":"Rambo","text":"Serious dog, serious kennel. They turned down our first choice because it did not suit our children, and they were right."}]}'::jsonb),
('STR-002', 'naija-guard-dogs', 'Naija Guard Dogs', 'NG', 'Family protection dogs raised around children', 'Lagos', 'Lekki', 'Lagos', 2016, 'verified', 4.8, 61, '{"replies":"~2 h","dogsPlaced":148,"hours":"Tue–Sun, 9am–6pm","deliveryAreas":"Lagos, Ogun, Ibadan","services":["handover","puppies","training","boarding"],"owner":{"name":"Chiamaka Eze","title":"Owner and breeder","yearsWithDogs":14,"bio":"Chiamaka started breeding after her own family dog stopped a break-in. She focuses on calm, clear-headed dogs that live indoors with children.","credentials":["KCN registered breeder","Canine behaviour diploma"]},"about":"A family-run kennel in Lekki raising Shepherds, Rottweilers and Cane Corsos inside the home. Puppies meet children, visitors and traffic before they leave.","history":[{"year":2016,"text":"First litter of German Shepherds raised at home in Lekki"},{"year":2019,"text":"Moved to a dedicated half-acre site with a puppy house"},{"year":2022,"text":"Started a family protection programme for adult dogs"},{"year":2026,"text":"Passed Dogeash kennel inspection"}],"inspection":{"status":"passed","date":"February 2026","by":"Dogeash inspection team","checks":["Puppies socialised with children","Vet records for every dog","Clean water and shade","Microchips scanned and matched"]},"care":[{"providerId":"CARE-04","relationship":"Our vet"},{"providerId":"CARE-05","relationship":"Grooming and cleaning"},{"providerId":"CARE-06","relationship":"Equipment we use"}],"reviewSamples":[{"name":"Femi A.","city":"Ikoyi","date":"Jul 2026","rating":5,"dog":"Nova","text":"Nova sleeps outside our children''s room and barks at the gate. Exactly the balance we asked for."},{"name":"Grace N.","city":"Ajah","date":"Mar 2026","rating":4,"text":"Great dog and honest advice. Delivery took a week longer than promised."}]}'::jsonb),
('STR-003', 'niger-delta-k9', 'Niger Delta K9', 'ND', 'Fast, driven dogs for compounds and oil-sector sites', 'Port Harcourt', 'GRA Phase 2', 'Rivers', 2012, 'verified', 4.7, 38, '{"replies":"~3 h","dogsPlaced":176,"hours":"Mon–Fri, 8am–4pm","deliveryAreas":"Rivers, Enugu, Abia, Bayelsa","services":["handover","delivery","training"],"owner":{"name":"Tamuno Briggs","title":"Managing director","yearsWithDogs":18,"bio":"Tamuno supplied patrol dogs to industrial sites for years before opening the kennel to families. Two sites: Port Harcourt and Enugu.","credentials":["Industrial K9 handler","PSA decoy certified"]},"about":"Two kennel sites in Port Harcourt and Enugu supplying Malinois, Dobermans and Rottweilers to homes, estates and industrial compounds across the South-South and South-East.","history":[{"year":2012,"text":"Started supplying patrol dogs to industrial sites"},{"year":2018,"text":"Opened to private homes and estates"},{"year":2021,"text":"Opened a second kennel site in Enugu"},{"year":2025,"text":"Passed Dogeash kennel inspection"}],"inspection":{"status":"passed","date":"December 2025","by":"Dogeash inspection team","checks":["Both sites visited","Vet records for every dog","Protection levels tested on site","Microchips scanned and matched"]},"care":[{"providerId":"CARE-07","relationship":"Our vet"},{"providerId":"CARE-02","relationship":"Refresher training partner"}],"reviewSamples":[{"name":"Ebiere T.","city":"Port Harcourt","date":"Jun 2026","rating":5,"dog":"Diesel","text":"Diesel patrols our yard every night. The team came back a month later to check on him at no charge."}]}'::jsonb),
('STR-004', 'savanna-working-dogs', 'Savanna Working Dogs', 'SW', 'Big, calm guardians for houses and compounds', 'Ibadan', 'Akobo', 'Oyo', 2018, 'verified', 4.8, 45, '{"replies":"~2 h","dogsPlaced":97,"hours":"Mon–Sat, 9am–5pm","deliveryAreas":"Oyo, Ogun, Osun, Lagos","services":["handover","puppies","boarding"],"owner":{"name":"Adebayo Ogunleye","title":"Owner","yearsWithDogs":11,"bio":"A veterinary nurse turned breeder, Adebayo is known for steady, low-drama Rottweilers and Cane Corsos.","credentials":["Veterinary nursing certificate","KCN registered breeder"]},"about":"A small kennel in Akobo focusing on Rottweilers, Cane Corsos and German Shepherds with strong nerves and a calm off-switch. Ideal for first-time guard dog owners.","history":[{"year":2018,"text":"First Rottweiler litter"},{"year":2021,"text":"Added Cane Corso and German Shepherd lines"},{"year":2026,"text":"Passed Dogeash kennel inspection"}],"inspection":{"status":"passed","date":"February 2026","by":"Dogeash inspection team","checks":["Clean, shaded kennel runs","Vet records for every dog","Temperament tested with visitors","Microchips scanned and matched"]},"care":[{"providerId":"CARE-08","relationship":"Our vet"},{"providerId":"CARE-03","relationship":"Kennel runs we recommend"}],"reviewSamples":[{"name":"Kemi L.","city":"Bodija","date":"Sep 2026","rating":5,"dog":"Tank","text":"First guard dog for us. Adebayo answered every question, even after we paid."}]}'::jsonb),
('STR-005', 'northern-ridge-k9', 'Northern Ridge K9', 'NR', 'Boerboels and Dutch Shepherds bred for heat and open land', 'Kano', 'Nassarawa GRA', 'Kano', 2019, 'verified', 4.6, 29, '{"replies":"~4 h","dogsPlaced":64,"hours":"Sat–Thu, 8am–4pm","deliveryAreas":"Kano, Kaduna, Jos, Abuja","services":["handover","delivery","puppies"],"owner":{"name":"Musa Abdullahi","title":"Founder","yearsWithDogs":9,"bio":"Musa breeds for the northern climate: short coats, strong heat tolerance and dogs that cover large compounds and farms.","credentials":["KCN registered breeder"]},"about":"A kennel in Kano breeding Boerboels and Dutch Shepherds for large compounds, farms and estates in the north, with partner handlers in Kaduna and Jos.","history":[{"year":2019,"text":"Founded with a Boerboel breeding pair"},{"year":2022,"text":"Added Dutch Shepherds for active protection work"},{"year":2025,"text":"Passed Dogeash kennel inspection"}],"inspection":{"status":"passed","date":"October 2025","by":"Dogeash inspection team","checks":["Shade and water for hot season","Vet records for every dog","Microchips scanned and matched"]},"care":[{"providerId":"CARE-09","relationship":"Our vet"}],"reviewSamples":[{"name":"Hauwa M.","city":"Kaduna","date":"Apr 2026","rating":4,"dog":"Cobra","text":"Very fit, very fast dog. Ask for the handover session; it makes a difference."}]}'::jsonb),
('STR-006', 'eastgate-k9-academy', 'Eastgate K9 Academy', 'EK', 'Training academy now listing its own graduates', 'Enugu', 'Independence Layout', 'Enugu', 2021, 'in_review', 0, 0, '{"replies":"~6 h","dogsPlaced":0,"hours":"Mon–Sat, 8am–6pm","deliveryAreas":"Enugu, Anambra, Ebonyi","services":["training","boarding"],"owner":{"name":"Ngozi Okafor","title":"Head trainer","yearsWithDogs":8,"bio":"Ngozi runs obedience and protection courses for owners in the South-East and is preparing her first dogs for sale.","credentials":["Canine behaviour diploma"]},"about":"A training academy in Enugu. Its dogs will appear here once Dogeash has inspected the kennel.","history":[{"year":2021,"text":"Opened as a training school for privately owned dogs"},{"year":2026,"text":"Applied to open a store on Dogeash"}],"inspection":{"status":"booked","date":"November 2026","by":"Dogeash inspection team","checks":[]},"care":[],"reviewSamples":[]}'::jsonb)
insert into public.dogs (file_no, store_id, name, breed, sex, city, age, weight_kg, hips, level, price_naira, status, photo_path, property, safe_with_children, file) values
('KD-2026-003', (select id from public.stores where public_id = 'STR-001'), 'Rambo', 'Belgian Malinois', 'Male', 'Abuja', '2.5 years', 32, 'A1', 5, 3200000, 'available', 'dogs/rambo-malinois.jpg', '{home,estate,compound}'::public.property_type[], true, '{"summary":"Imported Belgian working line male with full IGP-3 training. A serious deterrent for high-profile households: explosive drive on the field, calm and social indoors.","born":"12 February 2024 — K9 Guardian Kennels, Abuja","hipsElbows":"Hips A1 (a-normal) / elbows normal, SV certified","microchip":"985 112 004 716 204","vaccinations":"Full puppy series complete; annual booster due February 2027","titles":"IGP-3 (obedience, tracking, protection)","sire":"V Django vom Wolfsbane (NL)","dam":"Xira des Guerriers Belges (BE)","inspected":"Breed survey inspected November 2025","bestSuited":"Executive homes and gated estates needing an elite response dog handled by experienced owners","traits":["IGP-3 titled","Elite bitework","Bombproof nerves","Travels well","Doorway alert"]}'::jsonb),
('KD-2026-014', (select id from public.stores where public_id = 'STR-001'), 'Sarge', 'German Shepherd', 'Male', 'Abuja', '2 years', 38, 'A1', 4, 2400000, 'available', 'dogs/sarge-gsd.jpg', '{home,estate,compound}'::public.property_type[], true, '{"summary":"Deep-pigmented saddle male with an on/off switch most families ask for: full alert at the gate, gentle with the children he was raised beside.","born":"12 March 2024 — K9 Guardian Kennels, Abuja","hipsElbows":"Hips A1 (a-normal) / elbows normal, SV certified","microchip":"985 112 004 716 311","vaccinations":"Full series complete; booster due March 2027","titles":"IGP-1 obedience and protection","sire":"V Tell vom Adlerblut (DE)","dam":"V Asha of Guardian Line (NG)","inspected":"SV breed survey inspected November 2025","bestSuited":"Families in gated estates wanting a visible deterrent with controlled aggression on command","traits":["Stable nerve","High prey drive","Obedience titled","Crate trained","Kid friendly"]}'::jsonb),
('KD-2026-021', (select id from public.stores where public_id = 'STR-002'), 'Nova', 'German Shepherd', 'Female', 'Lagos', '18 months', 30, 'A2', 3, 1650000, 'available', 'dogs/nova-gsd.jpg', '{home,estate}'::public.property_type[], true, '{"summary":"Sable female with an exceptional nose and a soft mouth around small children. Barks early, bites only when commanded — the ideal first protection dog.","born":"3 June 2024 — Naija Guard Dogs, Lagos","hipsElbows":"Hips A2 (a-fast normal) / elbows normal","microchip":"985 113 002 884 917","vaccinations":"Complete puppy series; booster due June 2027","titles":"Companion obedience (CD) and beginner protection","sire":"V Kaiser von Loyalheim (DE)","dam":"Ada of Naija Guard (NG)","inspected":"Inspected January 2026 by NGSD panel","bestSuited":"First-time protection-dog owners in bungalows and duplexes with young children","traits":["Early barker","Soft with kids","Food motivated","Travels calmly"]}'::jsonb),
('KD-2026-032', (select id from public.stores where public_id = 'STR-003'), 'Flash', 'Belgian Malinois', 'Female', 'Port Harcourt', '14 months', 26, 'A1', 4, 2100000, 'reserved', 'dogs/flash-malinois.jpg', '{home,estate,compound}'::public.property_type[], true, '{"summary":"Fast, precise young female already performing full bitework. Reserved pending home inspection — her next family wants a night-shift deterrent.","born":"22 August 2024 — Niger Delta K9, Port Harcourt","hipsElbows":"Hips A1 (a-normal) / elbows normal","microchip":"985 114 001 552 036","vaccinations":"Complete series; booster due August 2027","titles":"IGP-2 routine in training","sire":"Ch. Blade of Delta Line (NG)","dam":"Yaska du Renard (FR)","inspected":"Inspected December 2025","bestSuited":"Active families with secure fencing and time for daily drills","traits":["Explosive speed","Agile climber","High energy","Water confident"]}'::jsonb),
('KD-2026-008', (select id from public.stores where public_id = 'STR-004'), 'Tank', 'Rottweiler', 'Male', 'Ibadan', '3 years', 52, 'B1', 4, 1900000, 'available', 'dogs/tank-rottweiler.jpg', '{home,compound}'::public.property_type[], true, '{"summary":"A physical wall of a dog. Tank holds a doorway by presence alone; his deep bark has ended three break-in attempts at his current home without contact.","born":"5 January 2023 — Savanna Working Dogs, Ibadan","hipsElbows":"Hips B1 (fast normal) / elbows clear","microchip":"985 115 003 220 741","vaccinations":"Complete; rabies current to January 2027","titles":"Family protection certified (level 2)","sire":"GCh. Bruno vom Starken Rott (DE)","dam":"Nkechi of Savanna (NG)","inspected":"ADRK-style survey February 2026","bestSuited":"Walled compounds and farmsteads needing a single-dog deterrent","traits":["Deep deterrent bark","Imposing size","Low energy indoors","Gate trained"]}'::jsonb),
('KD-2026-027', (select id from public.stores where public_id = 'STR-002'), 'Bella', 'Rottweiler', 'Female', 'Lagos', '2 years', 42, 'B2', 3, 1400000, 'available', 'dogs/bella-rottweiler.jpg', '{home,estate}'::public.property_type[], true, '{"summary":"Compact female that suits a duplex lifestyle: quiet through the day, tireless through the night. Alert-bark trained and housebroken.","born":"17 April 2024 — Naija Guard Dogs, Lagos","hipsElbows":"Hips B2 (fast normal) / elbows clear","microchip":"985 115 003 220 789","vaccinations":"Complete; booster due April 2027","titles":"Family protection certified (level 1)","sire":"Ch. Apollo of Lekki Line (NG)","dam":"Greta vom Hause Neumann (DE)","inspected":"Inspected February 2026","bestSuited":"Apartments and duplexes in serviced estates","traits":["Quiet indoors","Night alert","Housebroken","Good on lead"]}'::jsonb),
('KD-2026-017', (select id from public.stores where public_id = 'STR-003'), 'Diesel', 'Doberman Pinscher', 'Male', 'Enugu', '2 years', 40, 'A1', 4, 1750000, 'available', 'dogs/diesel-doberman.jpg', '{home,estate}'::public.property_type[], true, '{"summary":"Sleek perimeter patroller with European bloodlines. Covers a fence line faster than any dog in our kennel and shadows his handler room to room.","born":"9 September 2024 — Niger Delta K9, Enugu","hipsElbows":"Hips A1 / elbows normal, DCA evaluated","microchip":"985 116 002 013 558","vaccinations":"Complete; booster due September 2027","titles":"SCG-level protection dog certification","sire":"EU Ch. Falcon di Nero (IT)","dam":"Amara of Delta K9 (NG)","inspected":"Cardiac and hip screen December 2025","bestSuited":"Homes with large compounds and a jogging or security-conscious owner","traits":["Fastest patroller","Velcro handler dog","Heat tolerant","Crate trained"]}'::jsonb),
('KD-2026-036', (select id from public.stores where public_id = 'STR-001'), 'Kaia', 'Doberman Pinscher', 'Female', 'Abuja', '16 months', 30, 'A2', 3, 1500000, 'reserved', 'dogs/kaia-doberman.jpg', '{home}'::public.property_type[], true, '{"summary":"Sweet-natured female finishing her alert-bark program. Reserved for a family in Maitama; contact the kennel to join the waiting list for her littermate.","born":"30 July 2024 — K9 Guardian Kennels, Abuja","hipsElbows":"Hips A2 (preliminary) / elbows normal","microchip":"985 116 002 013 604","vaccinations":"Complete series; booster due July 2027","titles":"Obedience certified, protection in training","sire":"EU Ch. Falcon di Nero (IT)","dam":"Zuri of Guardian Line (NG)","inspected":"Inspected January 2026","bestSuited":"Families wanting a lighter-built guardian with strong people focus","traits":["People focused","Quick learner","Gentle mouth","Child tested"]}'::jsonb),
('KD-2026-005', (select id from public.stores where public_id = 'STR-002'), 'King', 'Cane Corso', 'Male', 'Lagos', '2.5 years', 50, 'B1', 4, 2200000, 'available', 'dogs/king-cane-corso.jpg', '{home,estate,compound}'::public.property_type[], true, '{"summary":"Black brindle corso with a chest like a barrel and the judgement to match. Property-aware: he distinguishes the gardener from a stranger within two visits.","born":"28 November 2023 — Naija Guard Dogs, Lagos","hipsElbows":"Hips B1 / elbows clear, ICCF evaluated","microchip":"985 117 001 934 275","vaccinations":"Complete; rabies current to November 2027","titles":"Family protection certified (level 2)","sire":"Ch. Escobar Mastini (IT)","dam":"Adaeze of Naija Guard (NG)","inspected":"Inspected February 2026","bestSuited":"Families with frequent visitors needing a discriminating guardian","traits":["Visitor discernment","Calm confidence","Drool moderate","Gate guardian"]}'::jsonb),
('KD-2026-029', (select id from public.stores where public_id = 'STR-004'), 'Duchess', 'Cane Corso', 'Female', 'Ibadan', '20 months', 41, 'B2', 3, 1800000, 'available', 'dogs/duchess-cane-corso.jpg', '{home,estate}'::public.property_type[], true, '{"summary":"Blue female with a watchful streak and a soft spot for teenagers. Trained to sleep across the front door corridor and challenge after dark.","born":"8 February 2024 — Savanna Working Dogs, Ibadan","hipsElbows":"Hips B2 / elbows clear","microchip":"985 117 001 934 318","vaccinations":"Complete; booster due February 2027","titles":"Family protection certified (level 1)","sire":"GCh. Nero Blu Corsi (IT)","dam":"Ijeoma of Savanna (NG)","inspected":"Inspected January 2026","bestSuited":"Bungalows and single-storey homes with night-time intrusion risk","traits":["Night challenger","Door corridor trained","Affectionate","Low prey chase"]}'::jsonb),
('KD-2026-011', (select id from public.stores where public_id = 'STR-005'), 'Boulder', 'Boerboel', 'Male', 'Kano', '2 years', 62, 'B1', 3, 850000, 'available', 'dogs/boulder-boerboel.jpg', '{home,compound}'::public.property_type[], true, '{"summary":"Homegrown brindle Boerboel bred for our climate — thick skin, low coat care and relentless loyalty to the whole household, from grandfather to toddler.","born":"14 May 2024 — Northern Ridge K9, Kano","hipsElbows":"Hips B1 / elbows clear, SABBS appraised","microchip":"985 118 004 655 190","vaccinations":"Complete; rabies current to May 2027","titles":"SABBS appraisal 88.5%","sire":"Dike of Northern Ridge (NG)","dam":"Hauwa of Northern Ridge (NG)","inspected":"SABBS appraisal October 2025","bestSuited":"Rural homesteads and farm compounds needing a robust livestock-aware guard","traits":["Heat hardened","Livestock aware","Frugal feeder","Immovable courage"]}'::jsonb),
('KD-2026-041', (select id from public.stores where public_id = 'STR-005'), 'Zara', 'Boerboel', 'Female', 'Jos', '7 months', 28, 'A2', 2, 550000, 'available', 'dogs/zara-boerboel.jpg', '{home,compound}'::public.property_type[], true, '{"summary":"Fawn puppy with 12 weeks of foundational guard training already banked: crate, lead, recall and bark-on-command foundation. Grows into a 55 kg guardian.","born":"22 March 2026 — Northern Ridge K9, Kano (raised in Jos)","hipsElbows":"Preliminary hips A2; formal scoring at 18 months","microchip":"985 118 004 655 233","vaccinations":"Full puppy series complete; next booster March 2027","titles":"Puppy foundation program (graduated)","sire":"Dike of Northern Ridge (NG)","dam":"Mai Tumbin of Jos Plateau (NG)","inspected":"Vet health check October 2026","bestSuited":"Families who want to raise a guardian alongside their children from puppyhood","traits":["Puppy trainable","Child raised","Recall started","Bark on cue (foundation)"]}'::jsonb),
