('KD-2026-049', (select id from public.stores where public_id = 'STR-005'), 'Cobra', 'Dutch Shepherd', 'Male', 'Kaduna', '20 months', 30, 'A2', 4, 1950000, 'available', 'dogs/cobra-dutch-shepherd.jpg', '{home,compound}'::public.property_type[], true, '{"summary":"Brindle KNPV-bred male with an off-switch that surprises everyone. Cobra works the fence line at a trot for hours, then lies under the dining table through dinner.","born":"19 February 2025 — Northern Ridge K9, Kaduna","hipsElbows":"Hips A2 (a-fast normal) / elbows normal","microchip":"985 119 004 776 012","vaccinations":"Complete series; booster due February 2027","titles":"KNPV-1 in training, obedience certified","sire":"Rex van de Bloemendaal (NL)","dam":"Sahara of Northern Ridge (NG)","inspected":"Inspected February 2026","bestSuited":"Active households and farms wanting a versatile all-weather worker","traits":["Endless stamina","Brindle working line","Social indoors","Heat hardened"]}'::jsonb),
('KD-2026-052', (select id from public.stores where public_id = 'STR-002'), 'Titus', 'Presa Canario', 'Male', 'Lagos', '3 years', 58, 'B1', 4, 2600000, 'reserved', 'dogs/titus-presa.jpg', '{compound}'::public.property_type[], true, '{"summary":"A fawn mountain with a black mask and the calm authority of a much older dog. Reserved for a consulate residence after a two-week trial; join the list for his half-brother.","born":"2 October 2023 — Naija Guard Dogs, Lagos","hipsElbows":"Hips B1 / elbows clear","microchip":"985 120 001 340 995","vaccinations":"Complete; rabies current to October 2027","titles":"Family protection certified (level 2)","sire":"Ch. Taz del Atlantico (ES)","dam":"Bianca of Naija Guard (NG)","inspected":"Inspected December 2025","bestSuited":"Large walled compounds with controlled visitor traffic","traits":["Immovable presence","Calm authority","Deep chest bark","Gate trained"]}'::jsonb),
('KD-2026-055', (select id from public.stores where public_id = 'STR-004'), 'Blitz', 'German Shepherd', 'Male', 'Ibadan', '20 months', 36, 'A1', 3, 1850000, 'available', 'dogs/blitz-gsd.jpg', '{home,estate}'::public.property_type[], true, '{"summary":"Solid black male from east-German working lines. Blitz tracks, alerts and holds — a natural with children and merciless on a trail.","born":"26 December 2024 — Savanna Working Dogs, Ibadan","hipsElbows":"Hips A1 (a-normal) / elbows normal","microchip":"985 120 002 918 663","vaccinations":"Complete; booster due December 2026","titles":"Tracking certified (IPH-1)","sire":"Quattro vom Felsenmeer (DE)","dam":"Ewu of Savanna (NG)","inspected":"Inspected January 2026","bestSuited":"Families who want tracking ability paired with home guarding","traits":["Elite tracker","Solid black coat","Kid friendly","Trainable daily"]}'::jsonb),
('KD-2026-058', (select id from public.stores where public_id = 'STR-001'), 'Mamba', 'Belgian Malinois', 'Female', 'Abuja', '3 years', 28, 'A1', 5, 2900000, 'available', 'dogs/mamba-malinois.jpg', '{home,estate,compound}'::public.property_type[], true, '{"summary":"Veteran of two embassy security contracts, now ready for a family that can keep up with her. Mamba reads a room in seconds and holds a perimeter like a drone with teeth.","born":"11 November 2023 — K9 Guardian Kennels, Abuja","hipsElbows":"Hips A1 (a-normal) / elbows normal, SV certified","microchip":"985 121 003 507 226","vaccinations":"Complete; booster due November 2026","titles":"IGP-3, executive protection certified","sire":"V Nikita des Loups Hardis (FR)","dam":"Keisha of Guardian Line (NG)","inspected":"Re-inspected February 2026","bestSuited":"Experienced handlers and high-profile homes with frequent travel","traits":["Contract veteran","Elite bitework","Vehicle trained","Fast response"]}'::jsonb),
